                lower_expression_to_ir1(
                    object,
                    ops,
                    bindings,
                    binding_lookup,
                    binding_index,
                    root_scope_id,
                    label_counter,
                    span_table,
                )?;
                ops.push(Ir1Op::StoreBinding {
                    binding_id: temp_obj,
                });
                ops.push(Ir1Op::Pop);

                // Short-circuit when the receiver is nullish.
                ops.push(Ir1Op::LoadBinding {
                    binding_id: temp_obj,
                });
                ops.push(Ir1Op::JumpIfNullish {
                    label_id: skip_label,
                });

