    #[test]
    fn scope_binding_ids_unique_single_scope() {
        let scope = ScopeNode {
            scope_id: ScopeId { depth: 0, index: 0 },
            parent: None,
            kind: ScopeKind::Global,
            bindings: vec![
                ResolvedBinding {
                    name: "a".to_string(),
                    binding_id: 0,
                    scope: ScopeId { depth: 0, index: 0 },
                    kind: BindingKind::Let,
                },
                ResolvedBinding {
                    name: "b".to_string(),
                    binding_id: 1,
                    scope: ScopeId { depth: 0, index: 0 },
                    kind: BindingKind::Let,
                },
            ],
        };
        assert!(scope_binding_ids_are_unique(&[scope]));
    }

    #[test]
    fn scope_binding_ids_duplicate_detected() {
        let scope = ScopeNode {
            scope_id: ScopeId { depth: 0, index: 0 },
            parent: None,
            kind: ScopeKind::Global,
            bindings: vec![
                ResolvedBinding {
                    name: "a".to_string(),
                    binding_id: 0,
                    scope: ScopeId { depth: 0, index: 0 },
                    kind: BindingKind::Let,
                },
                ResolvedBinding {
                    name: "b".to_string(),
                    binding_id: 0, // duplicate
                    scope: ScopeId { depth: 0, index: 0 },
                    kind: BindingKind::Let,
                },
            ],
        };
        assert!(!scope_binding_ids_are_unique(&[scope]));
    }

